module purification (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [15:0] grid [0:15],\n    output reg output_valid,\n    output reg [3:0] row_out,\n    output reg [3:0] col_out,\n    output reg done,\n    output reg no_solution\n);\n    \n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] CHECK_ROWS = 3'd1;\n    localparam [2:0] DECIDE = 3'd2;\n    localparam [2:0] OUTPUT = 3'd3;\n    localparam [2:0] OUTPUT_NEXT = 3'd4;\n    \n    reg [2:0] state;\n    reg [3:0] i;\n    reg [3:0] j;\n    reg [15:0] row_has_dot;\n    reg [15:0] col_has_dot;\n    reg [3:0] row_dot_col [0:15];\n    reg [3:0] col_dot_row [0:15];\n    reg [1:0] mode;\n    \n    integer k;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            output_valid <= 1'b0;\n            done <= 1'b0;\n            no_solution <= 1'b0;\n            i <= 4'd0;\n            j <= 4'd0;\n            row_has_dot <= 16'd0;\n            col_has_dot <= 16'd0;\n            mode <= 2'd0;\n            for (k = 0; k < 16; k = k + 1) begin\n                row_dot_col[k] <= 4'd0;\n                col_dot_row[k] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    output_valid <= 1'b0;\n                    done <= 1'b0;\n                    no_solution <= 1'b0;\n                    if (start) begin\n                        state <= CHECK_ROWS;\n                        i <= 4'd0;\n                        j <= 4'd0;\n                        row_has_dot <= 16'd0;\n                        col_has_dot <= 16'd0;\n                        for (k = 0; k < 16; k = k + 1) begin\n                            row_dot_col[k] <= 4'd0;\n                            col_dot_row[k] <= 4'd0;\n                        end\n                    end\n                end\n                \n                CHECK_ROWS: begin\n                    if (i < n) begin\n                        if (j < n) begin\n                            if (grid[i][j] == 1'b0) begin\n                                if (!row_has_dot[i]) begin\n                                    row_dot_col[i] <= j;\n                                end\n                                row_has_dot[i] <= 1'b1;\n                                \n                                if (!col_has_dot[j]) begin\n                                    col_dot_row[j] <= i;\n                                end\n                                col_has_dot[j] <= 1'b1;\n                            end\n                            j <= j + 4'd1;\n                        end else begin\n                            j <= 4'd0;\n                            i <= i + 4'd1;\n                        end\n                    end else begin\n                        i <= 4'd0;\n                        state <= DECIDE;\n                    end\n                end\n                \n                DECIDE: begin\n                    if ((&row_has_dot[0+:16]) && (&row_has_dot[0+:n])) begin\n                        mode <= 2'd0;\n                    end else if ((&col_has_dot[0+:16]) && (&col_has_dot[0+:n])) begin\n                        mode <= 2'd1;\n                    end else begin\n                        mode <= 2'd2;\n                    end\n                    i <= 4'd0;\n                    state <= OUTPUT;\n                end\n                \n                OUTPUT: begin\n                    if (mode == 2'd0 || mode == 2'd1) begin\n                        if (i < n) begin\n                            output_valid <= 1'b1;\n                            if (mode == 2'd0) begin\n                                row_out <= i + 4'd1;\n                                col_out <= row_dot_col[i] + 4'd1;\n                            end else begin\n                                row_out <= col_dot_row[i] + 4'd1;\n                                col_out <= i + 4'd1;\n                            end\n                            i <= i + 4'd1;\n                            state <= OUTPUT_NEXT;\n                        end else begin\n                            done <= 1'b1;\n                            state <= IDLE;\n                        end\n                    end else begin\n                        no_solution <= 1'b1;\n                        done <= 1'b1;\n                        state <= IDLE;\n                    end\n                end\n                \n                OUTPUT_NEXT: begin\n                    output_valid <= 1'b0;\n                    state <= OUTPUT;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule